SELECT percentile_cont(0.25) within GROUP (ORDER BY icustays.los) AS percentile_25 FROM patients JOIN admissions ON patients.subject_id = admissions.subject_id JOIN icustays ON admissions.stay_id = icustays.stay_id WHERE patients.gender = 'F' AND patients.anchor_age BETWEEN 67 AND 77 AND EXISTS (SELECT 1 FROM diagnoses_icd WHERE diagnoses_icd.subject_id = patients.subject_id AND diagnoses_icd.icd_code = '42605000');